                {/* Dropdown Content */}
                <div className="absolute top-full left-1/2 -translate-x-1/2 pt-4 w-[800px] hidden group-hover:block transition-all opacity-0 group-hover:opacity-100 animate-in fade-in slide-in-from-top-2">
