                <LogIn size={16} /> Login
              </button>
              <button className="bg-gradient-medical text-white px-5 py-2 rounded-full text-sm font-medium transition-all hover:shadow-glow flex items-center gap-2 shadow-md hover:-translate-y-0.5">
                Beratung <ArrowRight size={14} />
              </button>
            </div>

            {/* Empty spacer for mobile */}
            <div className="md:hidden w-8"></div> 
          </div>
        </div>
      </nav>

      {/* Mobile Menu Overlay */}
      {mobileOpen && (
        <div className="fixed inset-0 z-40 bg-white pt-24 px-6 animate-in fade-in slide-in-from-top-5 duration-200 overflow-y-auto pb-10">
          <div className="flex flex-col gap-6 text-center pb-10">
