    return <DashboardPage onLogout={handleLogout} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case 'home':
        return (
          <>
            <Hero />
            <FeatureFocus />
            <Products />
            <Testimonials />
            <section className="py-16 bg-white border-y border-slate-100">
              <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
