  const samples = [
    {
      id: 0,
      title: "Terminvereinbarung",
      desc: "Patient möchte einen Termin für die Akutsprechstunde.",
      duration: "0:45",
      icon: Calendar,
      color: "text-blue-600",
      bg: "bg-blue-100"
    },
    {
      id: 1,
      title: "Rezeptbestellung",
      desc: "Anforderung eines Folgerezepts für Blutdruckmittel.",
      duration: "0:30",
      icon: Pill,
      color: "text-emerald-600",
      bg: "bg-emerald-100"
    },
    {
