                        style={{ 
                          height: `${Math.max(20, Math.random() * 100)}%`,
                          animationDelay: `${i * 0.1}s` 
                        }} 
                      ></div>
                    ))}
                  </div>

                  {/* Fix: Ref callback must return void to avoid TS errors in some environments */}
                  <audio 
                    ref={(el) => { audioRefs.current[idx] = el; }}
                    src={sampleUrl}
                    onEnded={() => handleEnded(idx)}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <CTASection />
    </div>
  );
};

