                    // Fix: Wrapped assignment in braces to prevent returning the value, satisfying React.Ref callback type.
                    ref={el => { audioRefs.current[idx] = el; }}
                    src={sampleUrl}
                    onEnded={() => handleEnded(idx)}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <CTASection />
    </div>
  );
};

