import React, { useState, useEffect } from 'react';
import { Calculator, TrendingDown, Clock, Euro, ArrowRight } from 'lucide-react';

export const SavingsCalculator: React.FC = () => {
  const [callsPerDay, setCallsPerDay] = useState(25);
  const [avgCallDuration, setAvgCallDuration] = useState(3.5);
  const [hourlyRate, setHourlyRate] = useState(28);
  const [selectedPackage, setSelectedPackage] = useState<'Solo' | 'Team' | 'Business'>('Team');

  const [results, setResults] = useState({
    monthlyCalls: 0,
    timeSavedHours: 0,
    personnelCostOld: 0,
    aiCostNew: 0,
    monthlySavings: 0,
    roiPercent: 0,
    baseFee: 299
  });

  const packages = [
    { id: 'Solo', name: 'Solo', fee: 99, includedMins: 1000, extraMin: 0.15 },
    { id: 'Team', name: 'Team', fee: 299, includedMins: 3000, extraMin: 0.12 },
    { id: 'Business', name: 'Business', fee: 800, includedMins: 10000, extraMin: 0.10 }, // Schätzung für Business-Beispiel
  ];

  useEffect(() => {
    const WORK_DAYS_MONTH = 22;
    const EFFECTIVE_TALK_TIME_PER_HOUR = 35; // MFA telefoniert effektiv 35 Min/Std

    const monthlyCalls = callsPerDay * WORK_DAYS_MONTH;
    const totalMonthlyCallMinutes = monthlyCalls * avgCallDuration;

    // Status Quo Lohnkosten
    const paidHoursToCover = totalMonthlyCallMinutes / EFFECTIVE_TALK_TIME_PER_HOUR;
    const oldPersonnelCost = paidHoursToCover * hourlyRate;

    // Auxilium Kosten (Inklusivminuten Logik)
    const currentPkg = packages.find(p => p.id === selectedPackage) || packages[1];
    const extraMins = Math.max(0, totalMonthlyCallMinutes - currentPkg.includedMins);
    const totalAiCost = currentPkg.fee + (extraMins * currentPkg.extraMin);

    const netSavings = Math.max(0, oldPersonnelCost - totalAiCost);
    const roi = totalAiCost > 0 ? (netSavings / totalAiCost) * 100 : 0;

    setResults({
      monthlyCalls,
      timeSavedHours: Number((totalMonthlyCallMinutes / 60).toFixed(1)),
      personnelCostOld: Math.round(oldPersonnelCost),
      aiCostNew: Math.round(totalAiCost),
      monthlySavings: Math.round(netSavings),
      roiPercent: Math.round(roi),
      baseFee: currentPkg.fee
    });
  }, [callsPerDay, avgCallDuration, hourlyRate, selectedPackage]);

  return (
    <section className="py-24 bg-white relative overflow-hidden">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center max-w-4xl mx-auto mb-20">
          <h2 className="text-4xl md:text-5xl font-black text-slate-900 mb-8 tracking-tight overflow-visible">
            ROI Kalkulator: <br/><span className="text-gradient py-1">Inklusiv-Minuten nutzen.</span>
          </h2>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-stretch">
          <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-200 flex flex-col h-full">
            <div className="space-y-10 flex-1">
              <div className="space-y-4">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Tarif-Wahl</label>
                <div className="grid grid-cols-3 gap-2 p-1.5 bg-white border border-slate-200 rounded-2xl">
                  {packages.map((pkg) => (
                    <button key={pkg.id} onClick={() => setSelectedPackage(pkg.id as any)} className={`py-4 rounded-xl text-xs font-bold transition-all flex flex-col items-center gap-1 ${selectedPackage === pkg.id ? 'bg-primary text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>
                      <span>{pkg.name}</span><span className="text-[9px] font-medium opacity-80">{pkg.fee}€</span>
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-8">
                <div className="flex justify-between items-end">
                  <label className="font-bold text-slate-800 flex items-center gap-2"><TrendingDown size={18} className="text-primary" />Anrufe / Tag</label>
                  <div className="text-3xl font-black text-primary-dark">{callsPerDay}</div>
                </div>
                <input type="range" min="5" max="250" step="5" value={callsPerDay} onChange={(e) => setCallsPerDay(parseInt(e.target.value))} className="w-full h-2 bg-slate-200 rounded-lg appearance-none accent-primary" />
              </div>
              <div className="space-y-8">
                <div className="flex justify-between items-end">
                  <label className="font-bold text-slate-800 flex items-center gap-2"><Clock size={18} className="text-primary" />Dauer (Min)</label>
                  <div className="text-3xl font-black text-primary-dark">{avgCallDuration}</div>
                </div>
                <input type="range" min="1" max="10" step="0.5" value={avgCallDuration} onChange={(e) => setAvgCallDuration(parseFloat(e.target.value))} className="w-full h-2 bg-slate-200 rounded-lg appearance-none accent-primary" />
              </div>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-2xl h-full flex flex-col relative overflow-hidden">
            <div className="relative z-10 flex-1 flex flex-col h-full">
              <div className="mb-12">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Monatliche Ersparnis</p>
                <div className="text-6xl font-black text-slate-900 tracking-tighter leading-tight"><span className="text-gradient">+{results.monthlySavings.toLocaleString('de-DE')}€</span></div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">
                <div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Zeitgewinn</p>
                  <div className="flex items-baseline gap-2"><span className="text-4xl font-black text-slate-900">{results.timeSavedHours}</span><span className="text-xs font-bold text-slate-500">Std.</span></div>
                </div>
                <div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">ROI-Faktor</p>
                  <div className="flex items-baseline gap-2"><span className="text-4xl font-black text-slate-900">{results.roiPercent}</span><span className="text-xs font-bold text-slate-500">%</span></div>
                </div>
              </div>
              <div className="mt-auto pt-12">
                <button className="w-full bg-gradient-medical text-white py-6 rounded-3xl font-black text-xl shadow-2xl hover:shadow-glow hover:-translate-y-1 transition-all flex items-center justify-center gap-4">
                  Potential prüfen <ArrowRight size={24} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

