              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">
                <div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Zeitgewinn</p>
                  <div className="flex items-baseline gap-2"><span className="text-4xl font-black text-slate-900">{results.timeSavedHours}</span><span className="text-xs font-bold text-slate-500">Std.</span></div>
