            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

import React, { useState, useEffect } from 'react';
import { Calculator, TrendingDown, Clock, Euro, ArrowRight, Info } from 'lucide-react';

export const SavingsCalculator: React.FC = () => {
  // Inputs - Standardwert auf 1000 Minuten gesetzt (entspricht dem Inklusivvolumen Solo)
  const [monthlyMinutes, setMonthlyMinutes] = useState(1000);
  const [hourlyRate, setHourlyRate] = useState(28);
  const [selectedPackage, setSelectedPackage] = useState<'Solo' | 'Team'>('Solo');

  // Results State
  const [results, setResults] = useState({
    timeSavedHours: 0,
    personnelCostOld: 0,
    aiCostNew: 0,
    monthlySavings: 0,
    roiPercent: 0,
    baseFee: 99
  });

  // Nur Solo und Team im Rechner verfügbar
  const packages = [
    { id: 'Solo', name: 'Solo', fee: 99, includedMins: 1000, extraMin: 0.15 },
    { id: 'Team', name: 'Team', fee: 299, includedMins: 3000, extraMin: 0.12 },
  ];

  useEffect(() => {
    const EFFECTIVE_TALK_TIME_PER_HOUR = 35; // MFA telefoniert effektiv 35 Min pro bezahlter Stunde (Puffer/Vorbereitung)

    // 1. Zeitgewinn Anzeige (Netto Gesprächszeit)
    const netTimeSavedHours = monthlyMinutes / 60;

    // 2. Lohnkosten Kalkulation (Status Quo)
    const paidHoursToCover = monthlyMinutes / EFFECTIVE_TALK_TIME_PER_HOUR;
    const oldPersonnelCost = paidHoursToCover * hourlyRate;

    // 3. KI Kosten (Basierend auf Solo/Team)
    const currentPkg = packages.find(p => p.id === selectedPackage) || packages[0];
    const extraMins = Math.max(0, monthlyMinutes - currentPkg.includedMins);
    const totalAiCost = currentPkg.fee + (extraMins * currentPkg.extraMin);

    // 4. Netto Ersparnis & ROI
    const netSavings = Math.max(0, oldPersonnelCost - totalAiCost);
    const roi = totalAiCost > 0 ? (netSavings / totalAiCost) * 100 : 0;

    setResults({
      timeSavedHours: Number(netTimeSavedHours.toFixed(1)),
      personnelCostOld: Math.round(oldPersonnelCost),
      aiCostNew: Math.round(totalAiCost),
      monthlySavings: Math.round(netSavings),
      roiPercent: Math.round(roi),
      baseFee: currentPkg.fee
    });
  }, [monthlyMinutes, hourlyRate, selectedPackage]);

  return (
    <section className="py-24 bg-white relative overflow-hidden">
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-full bg-[radial-gradient(circle_at_40%_20%,_var(--tw-gradient-from)_0%,_transparent_50%)] from-primary-light/30 -z-10"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center max-w-4xl mx-auto mb-20">
          <div className="inline-flex items-center gap-2 text-primary-dark font-bold bg-primary-light/50 px-4 py-1.5 rounded-full text-[10px] uppercase tracking-[0.2em] mb-6 border border-primary/20">
            <Calculator size={14} />
            <span>Wirtschaftlichkeits-Kalkulator</span>
          </div>
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-black text-slate-900 mb-8 tracking-tight leading-[1.1] overflow-visible">
            Ihr Entlastungs-Potential <br/>
            <span className="text-gradient py-1">in harten Zahlen.</span>
          </h2>
          <p className="text-xl md:text-2xl text-slate-500 font-medium max-w-3xl mx-auto">
            Berechnen Sie Ihre Ersparnis basierend auf Ihrem monatlichen Gesprächsvolumen.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 items-stretch">

          {/* Eingabe-Sektion */}
          <div className="bg-slate-50 p-8 md:p-12 rounded-[3rem] border border-slate-200 shadow-sm flex flex-col h-full">
            <div className="space-y-10 flex-1">
              <div className="space-y-4">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em]">Gewählter Tarif</label>
                <div className="grid grid-cols-2 gap-2 p-1.5 bg-white border border-slate-200 rounded-2xl shadow-sm">
                  {packages.map((pkg) => (
                    <button
                      key={pkg.id}
                      onClick={() => setSelectedPackage(pkg.id as any)}
                      className={`py-4 rounded-xl text-xs font-bold transition-all flex flex-col items-center gap-1 ${
                        selectedPackage === pkg.id 
                        ? 'bg-primary text-white shadow-lg' 
                        : 'text-slate-400 hover:bg-slate-50'
                      }`}
                    >
                      <span>{pkg.name}</span>
                      <span className={`text-[9px] font-medium opacity-80 ${selectedPackage === pkg.id ? 'text-white' : 'text-slate-400'}`}>
                        {pkg.fee}€
                      </span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-8">
                <div className="flex justify-between items-end">
                  <label className="font-bold text-slate-800 text-base flex items-center gap-2 tracking-tight">
                    <Clock size={18} className="text-primary" />
                    Gesprächsminuten / Monat
                  </label>
                  <div className="text-3xl font-black text-primary-dark">{monthlyMinutes.toLocaleString('de-DE')}</div>
                </div>
                <input 
                  type="range" min="100" max="10000" step="100"
                  value={monthlyMinutes}
                  onChange={(e) => setMonthlyMinutes(parseInt(e.target.value))}
                  className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-primary"
                />
              </div>

              <div className="space-y-8">
                <div className="flex justify-between items-end">
                  <label className="font-bold text-slate-800 text-base flex items-center gap-2 tracking-tight">
                    <Euro size={18} className="text-primary" />
                    Lohnkosten MFA (€/h)
                  </label>
                  <div className="text-3xl font-black text-primary-dark">{hourlyRate}</div>
                </div>
                <input 
                  type="range" min="18" max="65" step="1"
                  value={hourlyRate}
                  onChange={(e) => setHourlyRate(parseInt(e.target.value))}
                  className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-primary"
                />
              </div>
            </div>

            <div className="pt-8 border-t border-slate-200 mt-10">
               <div className="bg-white/60 p-6 rounded-2xl border border-slate-200/50 flex gap-4">
                  <Info className="text-primary shrink-0" size={20} />
                  <p className="text-xs text-slate-500 leading-relaxed font-medium">
                    Inklusive {packages.find(p=>p.id===selectedPackage)?.includedMins} Freiminuten. Danach {packages.find(p=>p.id===selectedPackage)?.extraMin}€ / Minute.
                  </p>
               </div>
            </div>
          </div>

          {/* Ergebnis-Sektion */}
          <div className="bg-white p-8 md:p-12 rounded-[3rem] border border-slate-100 shadow-2xl h-full flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-primary/5 rounded-full blur-[100px] -mr-40 -mt-40"></div>

            <div className="relative z-10 flex-1 flex flex-col h-full">
              <div className="mb-12">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Monatliche Ersparnis</p>
                <div className="text-6xl md:text-7xl lg:text-8xl font-black text-slate-900 tracking-tighter overflow-visible">
                  <span className="text-gradient py-1">+{results.monthlySavings.toLocaleString('de-DE')}€</span>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">
                <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-center">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Zeitgewinn MFA</p>
                  <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-slate-900">{results.timeSavedHours.toLocaleString('de-DE')}</span>
                    <span className="text-sm font-bold text-slate-500 uppercase">Std.</span>
                  </div>
                </div>

                <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-center">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">ROI-Faktor</p>
                  <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-slate-900">{results.roiPercent}</span>
                    <span className="text-sm font-bold text-slate-500 uppercase">%</span>
                  </div>
                </div>
              </div>

              <div className="mt-auto pt-12">
                <button className="w-full bg-gradient-medical text-white py-6 rounded-3xl font-black text-xl shadow-2xl hover:shadow-glow hover:-translate-y-1 transition-all flex items-center justify-center gap-4">
                  Potential prüfen
                  <ArrowRight size={24} />
                </button>
              </div>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
};
